// E57 · GUARDA · la puerta de la sala contesta 200 hasta cuando RECHAZA
// (canon §150 G4 · cero presion de reintento sobre quien manda el sobre).
// Sin este nodo, un sobre mal armado se veria EXACTAMENTE igual que uno
// aceptado: 200 y silencio. Es la enfermedad de la casa, y aca se corta.
//
// E75 (CC#1 · 2026-09-17): `duplicate` sigue sin ser error (el mismo trato dos veces es un
// solo pedido), PERO si el sobre iba SIN identificador de trato, un `duplicate` puede ser
// OTRO trato del mismo cliente el mismo dia, colapsado en uno. Un descarte NO puede leerse
// como exito: se marca y el nodo siguiente AVISA a #alertas (patron E63/E68).
const r = $input.first().json;
const cuerpo = r.body || r;
if (cuerpo.ok !== true) {
  throw new Error('SOBRE_RECHAZADO · la puerta de la sala no acepto el sobre · code=' + (cuerpo.code || '?') + ' · ' + (cuerpo.detail || 'sin detalle'));
}
let armado = {};
try { armado = $('Armar el sobre').first().json || {}; } catch (e) { armado = {}; }
const descartadoSinIdentificador = cuerpo.kind === 'duplicate' && armado.sin_identificador === true;
return [{ json: {
  dejado_en_la_puerta: true,
  kind: cuerpo.kind,
  event_id: cuerpo.event_id || null,
  stream_id: cuerpo.stream_id || null,
  journey_type: cuerpo.journey_type || null,
  worker_workflow_id: cuerpo.worker_workflow_id || null,
  descartado_sin_identificador: descartadoSinIdentificador,
  client_id: armado.client_id || null,
  idempotency_key: armado.idempotency_key || null,
  fecha_del_trato: armado.fecha_del_trato || null,
} }];

// E75 · CC#1 · 2026-09-17 · ARMAR EL SOBRE del trato cerrado · la clave anti-repetidos
//
// 🔴 POR QUÉ EXISTE: con E73 la clave, sin deal_id, caía al cliente y el período quedó fijo
// («trato») ⇒ un cliente podía tener UNA sola alta en su vida; el segundo trato volvía
// `duplicate` y la GUARDA lo dejaba pasar como éxito (E74 · CC#2). Y lo normal hoy es que
// NO venga deal_id (el único payload real de un alta no lo trae; nadie lo genera).
//
// LA REGLA (Lenovo · E75):
//   1. con identificador de trato → se usa ése (deal_id | idempotency_key)
//   2. sin identificador → cliente + FECHA DEL TRATO (closed_at | deal_closed_at | won_at |
//      fecha_trato, o si no viene ninguna, la fecha de llegada) ⇒ un trato nuevo otro día
//      entra; un reintento del mismo día se descarta bien
//   3. ⚠️ salvedad declarada: dos tratos DISTINTOS del mismo cliente el MISMO día colapsan
//      en uno · por eso, si la puerta dice `duplicate` y no había identificador, se AVISA.
const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : {};

const dealId = String(body.deal_id || body.idempotency_key || '').trim();
const clientId = String(body.client_id || '').trim();
const tenantId = String(body.tenant_id || body.client_id || '').trim();

// la fecha del trato · primer campo legible · si no, la de llegada (UTC)
const candidatos = [body.closed_at, body.deal_closed_at, body.won_at, body.fecha_trato, body.closed_date];
let fechaDelTrato = null;
let fechaDeDonde = 'fecha de llegada';
for (let i = 0; i < candidatos.length; i++) {
  const c = candidatos[i];
  if (c === undefined || c === null || c === '') continue;
  const d = new Date(c);
  if (!isNaN(d.getTime())) { fechaDelTrato = d.toISOString().slice(0, 10); fechaDeDonde = ['closed_at', 'deal_closed_at', 'won_at', 'fecha_trato', 'closed_date'][i]; break; }
}
if (!fechaDelTrato) fechaDelTrato = new Date().toISOString().slice(0, 10);

const sinIdentificador = !dealId;
const idempotencyKey = sinIdentificador ? (clientId + ':' + fechaDelTrato) : dealId;

const sobre = {
  source: 'alta/deal-won',
  intent: 'onboard',
  payload: body,
  idempotency_key: idempotencyKey,
  logical_period: 'trato',
  tenant_id: tenantId,
  client_id: clientId,
};

return [{ json: {
  sobre: sobre,
  idempotency_key: idempotencyKey,
  sin_identificador: sinIdentificador,
  deal_id: dealId || null,
  client_id: clientId,
  fecha_del_trato: fechaDelTrato,
  fecha_de_donde: fechaDeDonde,
} }];

// E75 · el aviso no depende de que el aviso llegue · MISMO patron que E63 (reconciliador),
// E68 (vigia) y E73 (avisador de errores): `AVISO · #alertas` tiene onError:continueRegularOutput
// + alwaysOutputData, asi que un rechazo de Slack (200 + ok:false · 4xx/5xx · tiempo agotado)
// llega aca como item. Solo cuenta como avisado lo que Slack confirmo con ok:true; todo lo demas
// termina ESTA corrida en ERROR (visible en el motor · y el avisador de errores NO aplica aqui:
// el llamador no tiene errorWorkflow, asi que el error queda en su propia lista).
const g = $('GUARDA · si la puerta rechazó, se detiene').first().json || {};
const respuestas = $input.all().map(function (i) { return i.json || {}; });
const confirmadas = respuestas.filter(function (r) { return r.ok === true; });
if (respuestas.length === 0 || confirmadas.length !== respuestas.length) {
  const r = respuestas.find(function (x) { return x.ok !== true; }) || {};
  const causa = r.error
    ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)))
    : (respuestas.length === 0 ? 'Slack no devolvio respuesta' : 'Slack no confirmo ok:true · ' + JSON.stringify(r).slice(0, 200));
  throw new Error('[trato-cerrado] TRATO DESCARTADO SIN IDENTIFICADOR y el aviso NO llego a #alertas · ' + String(causa).slice(0, 300) + ' · cliente ' + g.client_id + ' · clave ' + g.idempotency_key);
}
console.log('[trato-cerrado] descarte sin identificador AVISADO · ts ' + confirmadas[0].ts + ' · cliente ' + g.client_id);
return [{ json: Object.assign({}, g, { aviso_ts: confirmadas[0].ts, aviso_canal: confirmadas[0].channel }) }];

// E79 · CC#1 · PORTERO · la llave de la entrada de trato cerrado (cabecera x-deal-won-key =
// DEAL_WON_WEBHOOK_KEY del motor · comparacion de largo constante · sin llave en el motor, CERRADO ·
// el rechazo NO ensena que mandar).
// E81 · CC#1 · 2026-09-17 · este nodo solo DECIDE. El rechazo se cuenta en una fila durable de
// `settings` (trato_cerrado.rechazos_portero · sobrevive a las 4 h del motor) y DESPUES se lanza
// con el motivo (corrida en error + aviso via el avisador, limitado por el freno). Se hace en
// nodos aparte porque el motor NO guarda la memoria del flujo cuando la corrida termina en error.
const raw = $input.first().json || {};
const headers = raw.headers || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : {};
const esperada = String($env.DEAL_WON_WEBHOOK_KEY || '').trim();
const recibida = String(headers['x-deal-won-key'] || '');
let iguales = esperada.length > 0 && recibida.length === esperada.length;
for (let i = 0; i < esperada.length; i++) {
  iguales = (recibida.charCodeAt(i) === esperada.charCodeAt(i)) && iguales;
}
const rechazado = !esperada || !iguales;
const tipo = !esperada ? 'entrada_cerrada' : (!recibida ? 'sin_llave' : 'llave_incorrecta');
const motivo = !esperada ? 'ENTRADA_CERRADA · el motor no tiene DEAL_WON_WEBHOOK_KEY'
  : (!recibida ? 'RECHAZADO_EN_EL_PORTERO · sin llave' : 'RECHAZADO_EN_EL_PORTERO · llave incorrecta');
return [{ json: Object.assign({}, raw, { _portero: {
  rechazado: rechazado,
  tipo: tipo,
  motivo: motivo,
  ip: headers['x-real-ip'] || headers['x-forwarded-for'] || null,
  client_id: body.client_id || null,
  deal_id: body.deal_id || null,
  at: new Date().toISOString(),
} }) }];

// E79 · GUARDA · el cliente tiene que EXISTIR · un identificador con formato correcto no es un cliente
//
// La puerta de la sala y el repartidor no consultan `clients`; el freno de gasto es por cliente
// ⇒ un UUID inventado por pedido lo esquivaba (E78 · CC#2). Acá, ANTES de dejar el sobre y antes
// de cualquier gasto: si el id no está en `clients`, rechazo RUIDOSO (lanza ⇒ el avisador de
// errores avisa; quien llega hasta acá ya pasó la llave, así que es señal, no ruido).
const r = $input.first().json || {};
const sc = Number(r.statusCode);
const body = r.body;
const armado = $('Armar el sobre').first().json || {};
if (!(sc >= 200 && sc < 300) || !Array.isArray(body)) {
  throw new Error('CLIENTE_NO_VERIFICABLE · no se pudo consultar clients (HTTP ' + (isNaN(sc) ? '?' : sc) + ') · el trato NO entra hasta poder comprobar que el cliente existe · ' + JSON.stringify(body).slice(0, 160));
}
if (body.length === 0) {
  throw new Error('CLIENTE_INEXISTENTE · el trato trae un client_id que no está en clients (' + String(armado.client_id).slice(0, 8) + '…) · un identificador con formato correcto no es un cliente · crear el cliente primero (POST /api/clients/upsert) y reenviar');
}
const cli = body[0];
if (cli.archived_at) {
  console.log('[trato-cerrado] aviso: el cliente ' + cli.id + ' está archivado (' + cli.archived_at + ') · el trato entra igual (cliente que vuelve)');
}
return [{ json: Object.assign({}, armado, { cliente_verificado: { id: cli.id, name: cli.name || null, status: cli.status || null, archived_at: cli.archived_at || null } }) }];

// E81 · suma el rechazo al contador durable (fila settings · trato_cerrado.rechazos_portero)
const p = $('PORTERO · llave del trato cerrado').first().json._portero || {};
const r = $input.first().json || {};
let actual = {};
try {
  const fila = Array.isArray(r.body) ? (r.body[0] || {}) : (Array.isArray(r) ? (r[0] || {}) : r);
  actual = JSON.parse(fila.value || '{}');
} catch (e) { actual = {}; }
const c = {
  total: (actual.total || 0) + 1,
  sin_llave: (actual.sin_llave || 0) + (p.tipo === 'sin_llave' ? 1 : 0),
  llave_incorrecta: (actual.llave_incorrecta || 0) + (p.tipo === 'llave_incorrecta' ? 1 : 0),
  entrada_cerrada: (actual.entrada_cerrada || 0) + (p.tipo === 'entrada_cerrada' ? 1 : 0),
  ultimo_at: p.at,
  ultimo_motivo: p.motivo,
  ultimos: ((actual.ultimos || []).concat([{ at: p.at, tipo: p.tipo, ip: p.ip, client_id: p.client_id, deal_id: p.deal_id, corrida: $execution.id }])).slice(-20),
};
return [{ json: { value: JSON.stringify(c), total: c.total, motivo: p.motivo, client_id: p.client_id } }];

// E81 · el rechazo ya quedo contado en settings · ahora se ve: corrida en ERROR con el motivo
// (y aviso a #alertas via el avisador, 1 cada 10 min por el freno que ya no se calla en falso).
const s = $('Sumar el rechazo').first().json || {};
const g = $input.first().json || {};
const guardado = Array.isArray(g.body) ? g.body.length > 0 : (Array.isArray(g) ? g.length > 0 : !!(g && g.key));
throw new Error(s.motivo + ' · pedido descartado antes de armar el sobre · cliente ' + String(s.client_id || '(sin client_id)').slice(0, 8)
  + ' · rechazos acumulados en el portero: ' + s.total + (guardado ? '' : ' (⚠️ el contador NO se pudo guardar en settings)')
  + ' · si es un CRM real, la llave x-deal-won-key esta vencida o mal copiada');

// NOCHE 19-oct · CC#1 · el cliente de cero ya tiene ficha: el pedido sigue como si hubiera traído su client_id.
const r = $input.first().json || {};
if (r.ok !== true || !r.client_id) throw new Error('FICHA_NO_CREADA — la puerta no pudo crear la ficha por nombre: ' + JSON.stringify(r).slice(0, 200));
const previo = $('¿Trae nombre y no trae client_id?').first().json || {};
const body = Object.assign({}, (previo.body && typeof previo.body === 'object') ? previo.body : {}, { client_id: r.client_id, tenant_id: r.client_id, _ficha_creada_por_la_puerta: r.creado === true });
return [{ json: Object.assign({}, previo, { body: body }) }];

